import { classNames, createElement } from './common/utils';
import buttonPresets from './common/buttonPresets';
import  { DatepickerOptions } from './Default';

import './DatepickerButtons.scss';

// Type for a button's content, which can be a string or a function returning a string
type ButtonContent = string | ((dp: any) => string);

// Interface for the button data object
export interface DatepickerButtonData {
    content: ButtonContent;
    onClick?: (dp: any) => void;
    className?: string;
    tagName?: string;
    attrs?: Record<string, string | number | boolean>;
}

interface DatepickerButtonsArgs {
    dp: any; // Replace with your Datepicker class type
    opts: DatepickerOptions;
}

export default class DatepickerButtons {
    dp: any;
    opts: DatepickerOptions;
    $el!: HTMLElement;

    constructor({ dp, opts }: DatepickerButtonsArgs) {
        this.dp = dp;
        this.opts = opts;

        this.init();
    }

    init(): void {
        this.createHtmlElement();
        this.render();
    }

    createHtmlElement(): void {
        this.$el = createElement({ className: 'datepicker-buttons' });
    }

    destroy(): void {
        this.$el.parentNode?.removeChild(this.$el);
    }

    clearHtml(): this {
        this.$el.innerHTML = '';
        return this;
    }

    generateButtons(): void {
        let { buttons } = this.opts;

        if (!buttons) return;

        // Ensure buttons is an array even if a single item is passed
        const buttonsArray = Array.isArray(buttons) ? buttons : [buttons];

        buttonsArray.forEach((b) => {
            let data: any

            // If it's a string, look up the preset
            if (typeof b === 'string' && (buttonPresets as any)[b]) {
                data = (buttonPresets as any)[b];
            }

            // At this point, if it's a valid button, it should be a DatepickerButtonData object
            if (typeof data !== 'string') {
                const button = this.createButton(data);
                
                if (data.onClick) {
                    this.attachEventToButton(button, data.onClick);
                }

                this.$el.appendChild(button);
            }
        });
    }

    attachEventToButton(button: HTMLElement, onClick: (dp: any) => void): void {
        button.addEventListener('click', () => {
            onClick(this.dp);
        });
    }

    /**
     * Creates datepicker button HTML element
     */
    createButton({
        content,
        className,
        tagName = 'button',
        attrs = {}
    }: DatepickerButtonData): HTMLElement {
        const _content = typeof content === 'function' ? content(this.dp) : content;

        return createElement({
            tagName,
            innerHtml: `<span tabindex='-1'>${_content}</span>`,
            className: classNames('datepicker-button', className),
            attrs
        });
    }

    render(): void {
        this.generateButtons();
    }
}